# 투표용지에 적힌 메뉴가 각각 몇 표인지 세어요.
votes = input().split()
counts = {}
for menu in votes:
    # 처음 보는 메뉴는 0표에서 시작해 한 표를 더해요.
    counts[menu] = counts.get(menu, 0) + 1
# sorted()는 이름을 알파벳 순서대로 꺼내줘요.
for menu in sorted(counts):
    print(menu, counts[menu])
